INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Präsentation des Projektergebnisses Teil der Abschlussphase?', 2, '[{"text": "Ja", "correct": true, "because": "Schließt Projekt ab"}, {"text": "Nein", "correct": false, "because": "Es gehört zum Abschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel hat die Präsentation des Projektergebnisses?', 3, '[{"text": "Ergebnisse den Stakeholdern zeigen", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Team direkt motivieren", "correct": false, "because": "Nebenaspekt"}, {"text": "Neue Ziele definieren", "correct": false, "because": "Initiierungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Präsentation zeigt den Erfolg. b) Sie erfolgt nur in der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Abschluss entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte gehören zur Präsentation des Projektergebnisses?', 4, '[{"text": "Projektziele und Erfüllung", "correct": true, "because": "Zeigen Erfolg"}, {"text": "Unklare Aussagen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Erreichte Ergebnisse", "correct": true, "because": "Kern der Präsentation"}, {"text": "Lessons Learned", "correct": true, "because": "Verbessern künftige Projekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Präsentation des Ergebnisses abgeschlossen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Stakeholder brauchen Rückmeldung"}, {"text": "Ja", "correct": false, "because": "Abnahme unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Präsentation?', 3, '[{"text": "Präsentationssoftware", "correct": true, "because": "Visualisiert Ergebnisse"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Nachweis"}, {"text": "Zufällige Notizen", "correct": false, "because": "Unprofessionell"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Präsentation nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Präsentation des Projektergebnisses?', 3, '[{"text": "Kommunikation des Erfolgs", "correct": true, "because": "Informiert Stakeholder"}, {"text": "Planung neu erstellen", "correct": false, "because": "Planungsaufgabe"}, {"text": "Team neu zusammenstellen", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Präsentation dient der Abnahme. b) Sie ist nur für den Projektleiter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Stakeholder betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Präsentation des Projektergebnisses?', 3, '[{"text": "Stakeholder bleiben uninformiert", "correct": true, "because": "Fehlende Rückmeldung"}, {"text": "Projekt wird schneller", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Kosten sinken", "correct": false, "because": "Akzeptanz unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Präsentation ohne Projektbericht erfolgen?', 2, '[{"text": "Ja", "correct": true, "because": "Mündlich möglich"}, {"text": "Nein", "correct": false, "because": "Flexibilität erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine gute Präsentation?', 3, '[{"text": "App-Funktionen mit Demo präsentieren", "correct": true, "because": "Klar und anschaulich"}, {"text": "Irgendwas zeigen", "correct": false, "because": "Zu vage"}, {"text": "Team soll reden", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Präsentation nur für den Kunden relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Team und Management betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Präsentation?', 4, '[{"text": "Ergebnisübersicht", "correct": true, "because": "Zeigt Erfolg"}, {"text": "Unklare Daten", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Vergleich mit Zielen", "correct": true, "because": "Bewertet Erfüllung"}, {"text": "Zukunftsempfehlungen", "correct": true, "because": "Bieten Mehrwert"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Präsentation dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt die Präsentation?', 3, '[{"text": "Visuelle Hilfsmittel", "correct": true, "because": "Veranschaulichen Ergebnisse"}, {"text": "Keine Struktur", "correct": false, "because": "Fehlt Klarheit"}, {"text": "Spontane Rede", "correct": false, "because": "Unvorbereitet wirkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Präsentation ohne Vorbereitung erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Professionalität nötig"}, {"text": "Ja", "correct": false, "because": "Risiko von Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Präsentation?', 3, '[{"text": "Unklare Ergebnisse", "correct": true, "because": "Verhindern Verständnis"}, {"text": "Gute Vorbereitung", "correct": false, "because": "Fördert Klarheit"}, {"text": "Klares Material", "correct": false, "because": "Unterstützt Vortrag"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Präsentation fördert Akzeptanz. b) Sie ist nur für technische Details.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Präsentation?', 3, '[{"text": "Transparenz über Ergebnisse", "correct": true, "because": "Informiert alle"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Rückmeldung", "correct": false, "because": "Fördert Verständnis"}]');
